// Fusionar todos los datos recopilados en un objeto unificado
const input    = $('Validar Formato TXN').first().json;
const txn      = $('Obtener Transacción').first().json || {};
const logsData = $('Obtener Logs').first().json || {};
const policies = $('Buscar Políticas').first().json || {};
const cases    = $('Buscar Casos Similares').first().json || {};
const sla      = $('Verificar SLA').first().json || {};

// Merchant y cliente: los flags ya vienen calculados por la API.
// Los umbrales viven en domain/constants.py, no en n8n.
let merchant = {};
try {
  merchant = $('Riesgo del Comercio').first().json;
} catch (e) { merchant = { error: e.message }; }

let client = {};
try {
  client = $('Historial del Cliente').first().json;
} catch (e) { client = { error: e.message }; }

const slaStatus = sla.within_sla != null
  ? (sla.within_sla
    ? `dentro de SLA (${sla.days_elapsed}d / ${sla.sla_limit_days}d)`
    : `FUERA de SLA (${sla.days_elapsed}d / ${sla.sla_limit_days}d)`)
  : 'SLA no calculado';

const agentAnalysis = [
  `Caso ${input.transaction_id}: ${txn.merchant || 'N/A'}, USD ${txn.amount_usd || 0},`,
  `canal ${txn.channel || 'N/A'}, país ${txn.country || 'N/A'}, score fraude ${txn.fraud_score ?? 'N/A'}.`,
  `Motivo: ${input.motivo || 'no especificado'}.`,
  `SLA: ${slaStatus}.`,
  `Cliente VIP: ${input.cliente_vip ? 'sí' : 'no'}.`,
  `Políticas encontradas: ${(policies.results || []).length}.`,
  `Casos similares: ${(cases.results || []).length}.`,
].join(' ');

return [{
  json: {
    transaction_id:  input.transaction_id,
    motivo:          input.motivo,
    cliente_vip:     input.cliente_vip,
    tx_data:         txn,
    logs:            logsData.logs || [],
    policies:        policies.results || [],
    similar_cases:   cases.results || [],
    merchant_risk:   merchant,
    client_history:  client,
    sla:             sla,
    agent_analysis:  agentAnalysis,
  }
}];

// Construir el payload exacto que espera POST /api/reports/html (ReportRequest)
const ctx        = $('Compilar Contexto').first().json;
const resolution = $('Sintetizar Resolución').first().json;
const judge      = $input.first().json.judge_evaluation || {
  overall_score: 5.0,
  criteria: {},
  approved: false,
  strengths: [],
  weaknesses: ['Judge evaluation unavailable'],
};

return [{
  json: {
    transaction:         ctx.tx_data,
    resolution:          resolution,
    judge_evaluation:    judge,
    agent_analysis:      ctx.agent_analysis,
    merchant_risk:       ctx.merchant_risk,
    client_profile:      ctx.client_history,
    logs:                ctx.logs,
    policies_evaluated:  resolution.policy_verdicts || [],
    similar_cases:       ctx.similar_cases,
    hitl_decision:       null,
    cache_hit:           false,
    guardrail_warnings:  resolution.guardrail_warnings || [],
    motivo:              ctx.motivo || '',
    cliente_vip:         ctx.cliente_vip || false,
  }
}];

// Cache hit: return JSON with cached flag + HTML
const html = $input.first().json.html;
return [{ json: { cached: true, html } }];

// Hacer visibles en el canvas los guardrails que ya corrieron en la API.
//
// Antes este nodo recalculaba los umbrales (1.1, 0.95, 2 fails) copiados de
// domain/constants.py. Eran una segunda fuente de verdad que nadie leia: los
// nodos de abajo releen $('Sintetizar Resolucion'), no la salida de este.
// Ahora solo resume lo que la API ya decidio.
const resolution = $input.first().json;
const warnings   = resolution.guardrail_warnings || [];

return [{
  json: {
    ...resolution,
    _guardrails: {
      total: warnings.length,
      warnings: warnings,
      status: warnings.length > 0 ? 'GUARDRAILS ACTIVADOS' : 'Sin alertas',
    },
  }
}];

// Procesar la decision del analista y armar el payload del informe.
//
// Falla CERRADO. Antes, la ausencia de decision caia en 'APPROVE' por defecto:
// un contracargo de riesgo alto se aprobaba solo y quedaba registrado como si
// lo hubiera aprobado una persona. Si el Wait vence sin respuesta, el caso sale
// marcado como pendiente y no se registra ninguna decision de analista.
const resume     = $input.first().json;
const ctx        = $('Compilar Contexto').first().json;
const resolution = $('Sintetizar Resolución').first().json;
const judge      = $('Extraer Evaluación — Juez').first().json.judge_evaluation || {
  overall_score: 5.0, criteria: {}, approved: false,
  strengths: [], weaknesses: ['Judge evaluation unavailable'],
};

// El formulario del Wait manda 'Decisión' / 'Notas del Analista'; una llamada
// directa al resumeUrl manda 'decision' / 'notes'.
const decisionCruda = String(resume['Decisión'] || resume.decision || '').trim();
const notasCrudas   = String(resume['Notas del Analista'] || resume.notes || '').trim();
const huboAnalista  = decisionCruda !== '';

const DECISION = decisionCruda.toUpperCase();

// El formulario ofrece tres opciones y esto mapeaba dos. `RECHAZA ? 'DENIED' :
// 'APPROVED'` metia MODIFY en la rama de APPROVED: un analista que eligio
// «modificar» quedaba registrado como si hubiera aprobado, y con judge >= 8 el
// caso se indexaba como precedente aprobado. Envenenaba el corpus que alimenta
// las decisiones siguientes.
const RESULTADO = {
  REJECT:   'DENIED',
  REJECTED: 'DENIED',
  MODIFY:   'MODIFIED',
  MODIFIED: 'MODIFIED',
  APPROVE:  'APPROVED',
  APPROVED: 'APPROVED',
};

const hitlDecision = huboAnalista
  ? {
      analyst_decision: DECISION,
      analyst_notes:    notasCrudas,
      // Sin mapeo conocido no se asume aprobacion: es lo mismo que hace el
      // resto del sistema con una entrada que no entiende.
      final_outcome:    RESULTADO[DECISION] || 'PENDING_HITL',
      timestamp:        new Date().toISOString(),
    }
  : {
      analyst_decision: 'SIN_RESPUESTA',
      analyst_notes:    'El plazo de espera vencio sin decision de un analista.',
      final_outcome:    'PENDING_HITL',
      timestamp:        new Date().toISOString(),
      timeout:          true,
    };

// El precedente se indexa desde la resolucion, y solo si una persona la avalo.
// Sin decision humana no se manda: un caso que nadie reviso no puede convertirse
// en el ejemplo con el que se resuelve el proximo.
const feedbackPayload = {
  transaction_id:   ctx.transaction_id,
  analyst_decision: hitlDecision.analyst_decision,
  analyst_notes:    hitlDecision.analyst_notes,
  final_outcome:    hitlDecision.final_outcome,
  judge_score:      judge.overall_score ?? 0,
  motivo:           ctx.motivo || null,
  // La resolucion viaja solo si el analista la avalo TAL CUAL. Con MODIFY la
  // aprobo con cambios que el sistema no tiene, asi que indexar esta version
  // como precedente seria guardar algo que nadie aprobo.
  resolution:       (huboAnalista && hitlDecision.final_outcome !== 'MODIFIED') ? resolution : null,
};

return [{
  json: {
    transaction:         ctx.tx_data,
    resolution:          resolution,
    judge_evaluation:    judge,
    agent_analysis:      ctx.agent_analysis,
    merchant_risk:       ctx.merchant_risk,
    client_profile:      ctx.client_history,
    logs:                ctx.logs,
    policies_evaluated:  resolution.policy_verdicts || [],
    similar_cases:       ctx.similar_cases,
    hitl_decision:       hitlDecision,
    cache_hit:           false,
    guardrail_warnings:  resolution.guardrail_warnings || [],
    motivo:              ctx.motivo || '',
    cliente_vip:         ctx.cliente_vip || false,
    _feedback_payload:   feedbackPayload,
  }
}];
